function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function pick(a){return a[Math.floor(Math.random()*a.length)]}
function adaptivePick(items,keyOf){
 const stats=playerGameStats(),previous=String(state.target||''),available=items.length>1?items.filter(item=>String(keyOf(item))!==previous):items;
 const reviews=playerProfile().reviews||{},due=available.filter(item=>{const review=reviews[`${state.game}:${String(keyOf(item))}`];return review&&review.due<=Date.now()});
 if(due.length&&Math.random()<.7)return pick(due);
 const practice=available.filter(item=>(stats.misses[String(keyOf(item))]||0)>0);
 const learned=available.filter(item=>(stats.concepts[String(keyOf(item))]||0)>0&&(stats.concepts[String(keyOf(item))]||0)<2&&!practice.includes(item));
 const fresh=available.filter(item=>!(stats.attempts[String(keyOf(item))]>0));
 const roll=Math.random(),bucket=roll<.7?practice:roll<.9?learned:fresh;
 return pick(bucket.length?bucket:practice.length?practice:fresh.length?fresh:learned.length?learned:available.length?available:items)
}
