function unlockedConcepts(game){if(game==='shapes')return progressiveConcepts(shapeLevels,game,4,7);if(game==='body')return progressiveConcepts(bodyLevels,game,8,18);if(animalLevels[game])return progressiveConcepts(animalLevels[game],game,4,game==='animals'?9:8);return null}
