function startLearningAdventure(type){const target=nextAdventureTarget(type),animalFinal=animalAdventureData[target]?.baby?'baby':'feature',steps=type==='letter'?[{game:'letters',mode:'press'},{game:'missingletter',mode:'find'},{game:'lettersound',mode:'word'}]:type==='number'?[{game:'numbers',mode:'press'},{game:'countobjects',mode:'count'},{game:'numbers',mode:'fingers',action:true}]:[{game:'animals',mode:'name'},{game:'animals',mode:'sound'},{game:'animals',mode:'habitat'},{game:'animals',mode:animalFinal}];state.journey=[];state.journeyMode=false;state.adventure={type,target,steps,step:0,player:who()};state.forcedTarget=type==='animal'?target.toUpperCase():String(target).toUpperCase();startAdventureStep()}
