function awardMilestone(certificate,onContinue,playerName=who()){const profile=playerProfile(playerName),specialAnimals=['CAT','DOLPHIN','LION','ELEPHANT'],animal=specialAnimals[(profile.certificates.length-1)%specialAnimals.length];el.earnedReward.innerHTML=`<span class="certificate-badge">${photoArt(animal)}<b>${certificate.label}</b></span>`;$('#rewardTitle').textContent='Learning milestone!';el.rewardMessage.textContent=`${playerName}, you unlocked a special ${animal.toLowerCase()} and a certificate!`;el.reward.hidden=false;state.rewardContinue=onContinue;setGuide('A learning milestone!',true);say(`${playerName}, wonderful learning! You unlocked a special ${animal.toLowerCase()} and a certificate.`);requestAnimationFrame(()=>$('#rewardContinue').focus())}
