 if(state.game==='missingletter'&&/^[A-Z]$/.test(raw))return `You found the matching ${raw}.`;
 if(['letters','name'].includes(state.game)&&/^[A-Z]$/.test(raw))return `Great! You found ${raw}.`;
 if(state.game==='lettersound'&&/^[A-Z]$/.test(raw))return `${raw} says ${phonics[raw]}.`;
 if(state.game==='numbers'&&/^\d$/.test(raw))return Number(raw)<=5?`This is number ${raw}. Show ${raw} on your fingers.`:`This is the number ${raw}.`;
 if(state.game==='countobjects'&&/^\d$/.test(raw))return `There are ${raw} objects.`;
 if(state.game==='colors')return `This color is ${friendlyLabel(raw)}.`;
 if(state.game==='shapes')return `This shape is a ${friendlyLabel(raw)}. Can you find one nearby?`;
 if(state.game==='actions')return `This action is ${friendlyLabel(raw)}. Can you copy it?`;
 if(state.game==='body')return `This is the ${friendlyLabel(raw)}. Can you touch yours?`;
