let deferredInstallPrompt=null;
const installButton=$('#installAppButton'),offlineButton=$('#prepareOfflineButton'),offlineStatus=$('#offlineStatus'),offlineProgress=$('#offlineProgress');
function installedAsApp(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
function updateOfflineStatus(message){if(offlineStatus)offlineStatus.textContent=message}
async function registerOfflineApp(){
 if(!('serviceWorker'in navigator)){updateOfflineStatus('This browser does not support offline installation.');offlineButton.disabled=true;return}
 try{
  await navigator.serviceWorker.register('./service-worker.js');
  await navigator.serviceWorker.ready;
  updateOfflineStatus(localStorage.getItem('emileeverseOfflineReady')==='1'?'Full library is ready offline.':'The game is ready offline. Download the full library for every lesson and voice.');
 }catch(error){console.error('Offline setup failed',error);updateOfflineStatus('Offline setup could not finish. Keep this page open and try again.')}
}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;if(!installedAsApp())installButton.hidden=false});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;installButton.hidden=true;updateOfflineStatus('EmileeVerse is installed. You can open it without internet.')});
installButton.addEventListener('click',async()=>{
 if(!deferredInstallPrompt){updateOfflineStatus(installedAsApp()?'EmileeVerse is already installed.':'Use your browser menu and choose Install app or Add to Home screen.');return}
 deferredInstallPrompt.prompt();
 await deferredInstallPrompt.userChoice;
 deferredInstallPrompt=null;
 installButton.hidden=true
});
offlineButton.addEventListener('click',async()=>{
 if(!('serviceWorker'in navigator)){updateOfflineStatus('Offline downloads are not supported in this browser.');return}
 offlineButton.disabled=true;offlineProgress.hidden=false;offlineProgress.value=0;updateOfflineStatus('Preparing the full offline library… Keep this page open.');
 try{
  if(navigator.storage?.persist)await navigator.storage.persist();
  const registration=await navigator.serviceWorker.ready;
  const worker=navigator.serviceWorker.controller||registration.active;
  if(!worker)throw new Error('No active offline worker');
  worker.postMessage({type:'CACHE_FULL_LIBRARY'});
 }catch(error){console.error('Full offline preparation failed',error);offlineButton.disabled=false;updateOfflineStatus('The download could not start. Please reload and try again.')}
});
navigator.serviceWorker?.addEventListener('message',event=>{
 const data=event.data||{};
 if(data.type==='OFFLINE_PROGRESS'){
  offlineProgress.value=data.total?Math.round(data.completed/data.total*100):0;
  updateOfflineStatus(`Preparing offline lessons: ${offlineProgress.value}%`)
 }
 if(data.type==='OFFLINE_COMPLETE'){
  offlineProgress.value=100;offlineButton.disabled=false;
  if(data.failed){localStorage.removeItem('emileeverseOfflineReady');updateOfflineStatus(`Offline preparation finished, but ${data.failed} files need another try.`)}
  else{localStorage.setItem('emileeverseOfflineReady','1');updateOfflineStatus('Full library is ready offline.');offlineButton.textContent='Refresh offline library'}
 }
});
