$('#changePlayers').addEventListener('click',()=>{stopSpeech();show(el.setup)});$('#setupButton').addEventListener('click',()=>{stopSpeech();show(el.setup)});$('#logoButton').addEventListener('click',()=>{stopSpeech();show(el.setup)});$('#backButton').addEventListener('click',()=>{state.soundCue='';state.adventure=null;state.forcedTarget=null;state.physicalChallenge=false;stopSpeech();stopRealSound();renderLibrary();show(el.library);requestAnimationFrame(()=>scrollTo(0,state.libraryScroll))});
document.addEventListener('keydown',handleKey);
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopGameAudio()});
window.addEventListener('pagehide',stopGameAudio);
window.addEventListener('beforeunload',stopGameAudio);
